=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO block with interrupts.
// Implements interface_spec.md through microarchitecture.md (approved).
`default_nettype none

module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0 to N-1 set: the pins that exist.
    localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'd1 << N) - 32'd1);

    localparam [3:0] IDX_DATA_OUT  = 4'd0;
    localparam [3:0] IDX_DIR       = 4'd1;
    localparam [3:0] IDX_DATA_IN   = 4'd2;
    localparam [3:0] IDX_RISE      = 4'd3;
    localparam [3:0] IDX_FALL      = 4'd4;
    localparam [3:0] IDX_HIGH      = 4'd5;
    localparam [3:0] IDX_LOW       = 4'd6;
    localparam [3:0] IDX_ENABLE    = 4'd7;
    localparam [3:0] IDX_STATUS    = 4'd8;

    // ------------------------------------------------------------------
    // Registers
    // ------------------------------------------------------------------
    reg [31:0] data_out;
    reg [31:0] dir;
    reg [31:0] intr_rise;
    reg [31:0] intr_fall;
    reg [31:0] intr_high;
    reg [31:0] intr_low;
    reg [31:0] intr_en;
    reg [31:0] status;
    reg [31:0] in_q;
    reg [31:0] in_prev;

    // ------------------------------------------------------------------
    // Input widened to 32 bits, zeros above N
    // ------------------------------------------------------------------
    wire [31:0] in_w;
    genvar gi;
    generate
        for (gi = 0; gi < 32; gi = gi + 1) begin : g_in
            if (gi < N) begin : g_pin
                assign in_w[gi] = gpio_in[gi];
            end else begin : g_zero
                assign in_w[gi] = 1'b0;
            end
        end
    endgenerate

    // ------------------------------------------------------------------
    // APB decode
    // ------------------------------------------------------------------
    wire       access     = psel & penable;
    wire [3:0] index      = paddr[5:2];
    wire       upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
    wire       mapped     = (paddr[1:0] == 2'b00) && upper_zero && (index <= IDX_STATUS);
    wire       wr_ok      = access & pwrite & mapped;
    wire       rd_ok      = access & ~pwrite & mapped;

    wire [31:0] wmask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

    wire we_data_out = wr_ok && (index == IDX_DATA_OUT);
    wire we_dir      = wr_ok && (index == IDX_DIR);
    wire we_rise     = wr_ok && (index == IDX_RISE);
    wire we_fall     = wr_ok && (index == IDX_FALL);
    wire we_high     = wr_ok && (index == IDX_HIGH);
    wire we_low      = wr_ok && (index == IDX_LOW);
    wire we_en       = wr_ok && (index == IDX_ENABLE);
    wire we_status   = wr_ok && (index == IDX_STATUS);

    // ------------------------------------------------------------------
    // Next state
    // ------------------------------------------------------------------
    wire [31:0] data_out_d  = we_data_out ? ((data_out  & ~wmask) | (pwdata & wmask)) : data_out;
    wire [31:0] dir_d       = we_dir      ? ((dir       & ~wmask) | (pwdata & wmask)) : dir;
    wire [31:0] intr_rise_d = we_rise     ? ((intr_rise & ~wmask) | (pwdata & wmask)) : intr_rise;
    wire [31:0] intr_fall_d = we_fall     ? ((intr_fall & ~wmask) | (pwdata & wmask)) : intr_fall;
    wire [31:0] intr_high_d = we_high     ? ((intr_high & ~wmask) | (pwdata & wmask)) : intr_high;
    wire [31:0] intr_low_d  = we_low      ? ((intr_low  & ~wmask) | (pwdata & wmask)) : intr_low;
    wire [31:0] intr_en_d   = we_en       ? ((intr_en   & ~wmask) | (pwdata & wmask)) : intr_en;

    wire [31:0] rise     = in_q & ~in_prev;
    wire [31:0] fall     = ~in_q & in_prev;
    wire [31:0] detected = ((rise & intr_rise) | (fall & intr_fall)
                          | (in_q & intr_high) | (~in_q & intr_low)) & PINS;
    wire [31:0] clear    = we_status ? (pwdata & wmask) : 32'h0000_0000;
    // A detection beats a clear: the OR comes last.
    wire [31:0] status_d = (status & ~clear) | detected;

    // ------------------------------------------------------------------
    // Register block: synchronous, active-low reset
    // ------------------------------------------------------------------
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out  <= 32'h0000_0000;
            dir       <= 32'h0000_0000;
            intr_rise <= 32'h0000_0000;
            intr_fall <= 32'h0000_0000;
            intr_high <= 32'h0000_0000;
            intr_low  <= 32'h0000_0000;
            intr_en   <= 32'h0000_0000;
            status    <= 32'h0000_0000;
            in_q      <= 32'h0000_0000;
            in_prev   <= 32'h0000_0000;
        end else begin
            data_out  <= data_out_d;
            dir       <= dir_d;
            intr_rise <= intr_rise_d;
            intr_fall <= intr_fall_d;
            intr_high <= intr_high_d;
            intr_low  <= intr_low_d;
            intr_en   <= intr_en_d;
            status    <= status_d;
            in_q      <= in_w;
            in_prev   <= in_q;
        end
    end

    // ------------------------------------------------------------------
    // Read multiplexer and responses
    // ------------------------------------------------------------------
    reg [31:0] rdata_mux;
    always @* begin
        rdata_mux = 32'h0000_0000;
        case (index)
            IDX_DATA_OUT: rdata_mux = data_out;
            IDX_DIR:      rdata_mux = dir;
            IDX_DATA_IN:  rdata_mux = in_q;
            IDX_RISE:     rdata_mux = intr_rise;
            IDX_FALL:     rdata_mux = intr_fall;
            IDX_HIGH:     rdata_mux = intr_high;
            IDX_LOW:      rdata_mux = intr_low;
            IDX_ENABLE:   rdata_mux = intr_en;
            IDX_STATUS:   rdata_mux = status;
            default:      rdata_mux = 32'h0000_0000;
        endcase
    end

    assign prdata  = rd_ok ? rdata_mux : 32'h0000_0000;
    assign pready  = 1'b1;
    assign pslverr = access & (~mapped | (pwrite & (index == IDX_DATA_IN)));

    assign gpio_out = data_out[N-1:0];
    assign gpio_oe  = dir[N-1:0];
    assign irq      = |(status & intr_en);

endmodule

`default_nettype wire
=== END FILE ===
