// apb_gpio_tb: self-checking testbench for apb_gpio at N = 8 and N = 32.
module apb_gpio_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel8;
    reg         psel32;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;

    wire [31:0] prdata8;
    wire        pready8;
    wire        pslverr8;
    reg  [7:0]  gpio_in8;
    wire [7:0]  gpio_out8;
    wire [7:0]  gpio_oe8;
    wire        irq8;

    wire [31:0] prdata32;
    wire        pready32;
    wire        pslverr32;
    reg  [31:0] gpio_in32;
    wire [31:0] gpio_out32;
    wire [31:0] gpio_oe32;
    wire        irq32;

    localparam [31:0] PINS8  = 32'h0000_00FF;
    localparam [31:0] PINS32 = 32'hFFFF_FFFF;

    localparam [7:0] A_DATA_OUT = 8'h00;
    localparam [7:0] A_DIR      = 8'h04;
    localparam [7:0] A_DATA_IN  = 8'h08;
    localparam [7:0] A_RISE     = 8'h0C;
    localparam [7:0] A_FALL     = 8'h10;
    localparam [7:0] A_HIGH     = 8'h14;
    localparam [7:0] A_LOW      = 8'h18;
    localparam [7:0] A_ENABLE   = 8'h1C;
    localparam [7:0] A_STATUS   = 8'h20;

    integer passed;
    integer failed;
    integer phase;
    integer ncheck;
    reg  [31:0] rd;
    reg         er;
    reg  [7:0]  a;
    reg  [8*64-1:0] nonce;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel8),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
        .gpio_in(gpio_in8), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8), .irq(irq8)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel32),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gpio_in32), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32), .irq(irq32)
    );

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // Expected-value model of a strobed write.
    function [31:0] merge;
        input [31:0] old;
        input [31:0] data;
        input [3:0]  strb;
        input [31:0] pins;
        reg   [31:0] m;
        begin
            m = {{8{strb[3]}}, {8{strb[2]}}, {8{strb[1]}}, {8{strb[0]}}} & pins;
            merge = (old & ~m) | (data & m);
        end
    endfunction

    task check32;
        input [31:0] got;
        input [31:0] exp;
        begin
            ncheck = ncheck + 1;
            if (got !== exp) begin
                failed = failed + 1;
                $error("phase %0d check %0d: got %h, expected %h", phase, ncheck, got, exp);
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    // One APB transfer. Starts at a falling edge, ends at a falling edge
    // with the bus idle, so consecutive calls are back to back.
    task xfer;
        input        which;
        input        wr;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        begin
            if (which) psel32 = 1'b1; else psel8 = 1'b1;
            penable = 1'b0;
            pwrite  = wr;
            paddr   = addr;
            pwdata  = wr ? data : 32'h0000_0000;
            pstrb   = wr ? strb : 4'h0;
            #1;
            // Setup phase: prdata and pslverr are zero.
            check32(which ? prdata32 : prdata8, 32'h0000_0000);
            check32({31'h0, (which ? pslverr32 : pslverr8)}, 32'h0000_0000);
            @(negedge pclk);
            penable = 1'b1;
            #1;
            rd = which ? prdata32 : prdata8;
            er = which ? pslverr32 : pslverr8;
            check32({31'h0, (which ? pready32 : pready8)}, 32'h0000_0001);
            @(negedge pclk);
            psel8   = 1'b0;
            psel32  = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            pstrb   = 4'h0;
            pwdata  = 32'h0000_0000;
            paddr   = 8'h00;
        end
    endtask

    task wr_chk;
        input        which;
        input [7:0]  addr;
        input [31:0] data;
        input [3:0]  strb;
        input        exp_err;
        begin
            xfer(which, 1'b1, addr, data, strb);
            check32({31'h0, er}, {31'h0, exp_err});
        end
    endtask

    task rd_chk;
        input        which;
        input [7:0]  addr;
        input [31:0] exp;
        input        exp_err;
        begin
            xfer(which, 1'b0, addr, 32'h0000_0000, 4'h0);
            check32(rd, exp);
            check32({31'h0, er}, {31'h0, exp_err});
        end
    endtask

    task idle;
        input integer n;
        begin
            repeat (n) @(negedge pclk);
        end
    endtask

    task check_ports;
        input        which;
        input [7:0]  addr;
        input [31:0] exp;
        begin
            if (addr == A_DATA_OUT)
                check32(which ? gpio_out32 : {24'h0, gpio_out8}, exp);
            if (addr == A_DIR)
                check32(which ? gpio_oe32 : {24'h0, gpio_oe8}, exp);
        end
    endtask

    task rw_test;
        input        which;
        input [7:0]  addr;
        input [31:0] pins;
        reg   [31:0] e;
        begin
            wr_chk(which, addr, 32'hFFFF_FFFF, 4'hF, 1'b0);
            e = pins;
            rd_chk(which, addr, e, 1'b0);
            check_ports(which, addr, e);

            wr_chk(which, addr, 32'h1234_5678, 4'b0101, 1'b0);
            e = merge(e, 32'h1234_5678, 4'b0101, pins);
            rd_chk(which, addr, e, 1'b0);
            check_ports(which, addr, e);

            wr_chk(which, addr, 32'hFFFF_FFFF, 4'b0000, 1'b0);
            rd_chk(which, addr, e, 1'b0);
            check_ports(which, addr, e);

            wr_chk(which, addr, 32'h0000_0000, 4'b1010, 1'b0);
            e = merge(e, 32'h0000_0000, 4'b1010, pins);
            rd_chk(which, addr, e, 1'b0);
            check_ports(which, addr, e);

            wr_chk(which, addr, 32'h0000_0000, 4'hF, 1'b0);
            rd_chk(which, addr, 32'h0000_0000, 1'b0);
            check_ports(which, addr, 32'h0000_0000);
        end
    endtask

    initial begin
        passed    = 0;
        failed    = 0;
        phase     = 0;
        ncheck    = 0;
        nonce     = {(8*64){1'b0}};
        presetn   = 1'b0;
        psel8     = 1'b0;
        psel32    = 1'b0;
        penable   = 1'b0;
        pwrite    = 1'b0;
        paddr     = 8'h00;
        pwdata    = 32'h0000_0000;
        pstrb     = 4'h0;
        gpio_in8  = 8'h00;
        gpio_in32 = 32'h0000_0000;
        rd        = 32'h0000_0000;
        er        = 1'b0;

        repeat (3) @(posedge pclk);
        @(negedge pclk);
        presetn = 1'b1;

        // Phase 1: reset values.
        phase = 1;
        for (a = 8'h00; a <= 8'h20; a = a + 8'h04) begin
            rd_chk(1'b0, a, 32'h0000_0000, 1'b0);
            rd_chk(1'b1, a, 32'h0000_0000, 1'b0);
        end
        check32({24'h0, gpio_out8}, 32'h0000_0000);
        check32({24'h0, gpio_oe8}, 32'h0000_0000);
        check32({31'h0, irq8}, 32'h0000_0000);
        check32(gpio_out32, 32'h0000_0000);
        check32(gpio_oe32, 32'h0000_0000);
        check32({31'h0, irq32}, 32'h0000_0000);

        // Phase 2: read/write registers, strobes, bits above N, pins.
        phase = 2;
        for (a = 8'h00; a <= 8'h1C; a = a + 8'h04) begin
            if (a != A_DATA_IN) begin
                rw_test(1'b0, a, PINS8);
                rw_test(1'b1, a, PINS32);
            end
        end

        // Phase 3: clear what the level enables set during phase 2.
        phase = 3;
        wr_chk(1'b0, A_STATUS, 32'hFFFF_FFFF, 4'hF, 1'b0);
        wr_chk(1'b1, A_STATUS, 32'hFFFF_FFFF, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        rd_chk(1'b1, A_STATUS, 32'h0000_0000, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0000);
        check32({31'h0, irq32}, 32'h0000_0000);

        // Phase 4: DATA_IN sampling and read-only behavior.
        phase = 4;
        gpio_in8  = 8'hA5;
        gpio_in32 = 32'hDEAD_BEEF;
        idle(1);
        rd_chk(1'b0, A_DATA_IN, 32'h0000_00A5, 1'b0);
        rd_chk(1'b1, A_DATA_IN, 32'hDEAD_BEEF, 1'b0);
        wr_chk(1'b0, A_DATA_IN, 32'h0000_0000, 4'hF, 1'b1);
        rd_chk(1'b0, A_DATA_IN, 32'h0000_00A5, 1'b0);
        wr_chk(1'b1, A_DATA_IN, 32'h0000_0000, 4'hF, 1'b1);
        rd_chk(1'b1, A_DATA_IN, 32'hDEAD_BEEF, 1'b0);
        // Input read with outputs enabled.
        wr_chk(1'b0, A_DIR, 32'h0000_00FF, 4'hF, 1'b0);
        wr_chk(1'b0, A_DATA_OUT, 32'h0000_000F, 4'hF, 1'b0);
        check32({24'h0, gpio_out8}, 32'h0000_000F);
        check32({24'h0, gpio_oe8}, 32'h0000_00FF);
        rd_chk(1'b0, A_DATA_IN, 32'h0000_00A5, 1'b0);
        wr_chk(1'b0, A_DIR, 32'h0000_0000, 4'hF, 1'b0);
        wr_chk(1'b0, A_DATA_OUT, 32'h0000_0000, 4'hF, 1'b0);
        gpio_in8  = 8'h00;
        gpio_in32 = 32'h0000_0000;
        idle(2);

        // Phase 5: PSLVERR policy and unmapped addresses.
        phase = 5;
        rd_chk(1'b0, 8'h24, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'h01, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'h02, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'h03, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'h21, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'h3C, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'h40, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'h80, 32'h0000_0000, 1'b1);
        rd_chk(1'b0, 8'hFC, 32'h0000_0000, 1'b1);
        rd_chk(1'b1, 8'h24, 32'h0000_0000, 1'b1);
        rd_chk(1'b1, 8'h42, 32'h0000_0000, 1'b1);
        wr_chk(1'b0, 8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr_chk(1'b0, 8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr_chk(1'b0, 8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr_chk(1'b0, 8'h5C, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr_chk(1'b1, 8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr_chk(1'b1, 8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
        rd_chk(1'b0, A_DATA_OUT, 32'h0000_0000, 1'b0);
        rd_chk(1'b0, A_ENABLE, 32'h0000_0000, 1'b0);
        rd_chk(1'b1, A_DATA_OUT, 32'h0000_0000, 1'b0);
        rd_chk(1'b1, A_DIR, 32'h0000_0000, 1'b0);
        check32({24'h0, gpio_out8}, 32'h0000_0000);
        check32(gpio_oe32, 32'h0000_0000);

        // Phase 6: rising edge fires once; interrupt mask.
        phase = 6;
        wr_chk(1'b0, A_RISE, 32'h0000_0003, 4'hF, 1'b0);
        gpio_in8 = 8'h01;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0001, 1'b0);
        idle(3);
        rd_chk(1'b0, A_STATUS, 32'h0000_0001, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0000);
        wr_chk(1'b0, A_STATUS, 32'h0000_0001, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        idle(3);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        gpio_in8 = 8'h03;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0002, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0000);
        wr_chk(1'b0, A_ENABLE, 32'h0000_0002, 4'hF, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0001);
        wr_chk(1'b0, A_ENABLE, 32'h0000_0001, 4'hF, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0000);
        rd_chk(1'b0, A_STATUS, 32'h0000_0002, 1'b0);
        wr_chk(1'b0, A_STATUS, 32'h0000_0002, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        wr_chk(1'b0, A_ENABLE, 32'h0000_0000, 4'hF, 1'b0);
        wr_chk(1'b0, A_RISE, 32'h0000_0000, 4'hF, 1'b0);

        // Phase 7: falling edge.
        phase = 7;
        wr_chk(1'b0, A_FALL, 32'h0000_0004, 4'hF, 1'b0);
        gpio_in8 = 8'h07;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        gpio_in8 = 8'h03;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0004, 1'b0);
        wr_chk(1'b0, A_STATUS, 32'h0000_0004, 4'hF, 1'b0);
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        wr_chk(1'b0, A_FALL, 32'h0000_0000, 4'hF, 1'b0);

        // Phase 8: high level sets again after a clear.
        phase = 8;
        wr_chk(1'b0, A_HIGH, 32'h0000_0010, 4'hF, 1'b0);
        gpio_in8 = 8'h13;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0010, 1'b0);
        wr_chk(1'b0, A_STATUS, 32'h0000_0010, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0010, 1'b0);
        gpio_in8 = 8'h03;
        idle(2);
        wr_chk(1'b0, A_STATUS, 32'h0000_0010, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        wr_chk(1'b0, A_HIGH, 32'h0000_0000, 4'hF, 1'b0);

        // Phase 9: low level.
        phase = 9;
        wr_chk(1'b0, A_LOW, 32'h0000_0020, 4'hF, 1'b0);
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0020, 1'b0);
        gpio_in8 = 8'h23;
        idle(2);
        wr_chk(1'b0, A_STATUS, 32'h0000_0020, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        wr_chk(1'b0, A_LOW, 32'h0000_0000, 4'hF, 1'b0);

        // Phase 10: clear some pending bits only; unstrobed clear; irq.
        phase = 10;
        wr_chk(1'b0, A_RISE, 32'h0000_00C0, 4'hF, 1'b0);
        gpio_in8 = 8'hE3;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_00C0, 1'b0);
        wr_chk(1'b0, A_ENABLE, 32'h0000_0080, 4'hF, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0001);
        wr_chk(1'b0, A_STATUS, 32'h0000_0040, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0080, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0001);
        wr_chk(1'b0, A_STATUS, 32'h0000_00FF, 4'h0, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0080, 1'b0);
        wr_chk(1'b0, A_STATUS, 32'h0000_0080, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        check32({31'h0, irq8}, 32'h0000_0000);
        wr_chk(1'b0, A_ENABLE, 32'h0000_0000, 4'hF, 1'b0);

        // Phase 11: a detection beats a clear on the same edge.
        phase = 11;
        wr_chk(1'b0, A_RISE, 32'h0000_0008, 4'hF, 1'b0);
        gpio_in8 = 8'hEB;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0008, 1'b0);
        gpio_in8 = 8'hE3;
        idle(2);
        rd_chk(1'b0, A_STATUS, 32'h0000_0008, 1'b0);
        // Pin rises at the setup edge; the rise is detected on the
        // completing edge of the clear.
        gpio_in8 = 8'hEB;
        wr_chk(1'b0, A_STATUS, 32'h0000_0008, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0008, 1'b0);
        wr_chk(1'b0, A_STATUS, 32'h0000_0008, 4'hF, 1'b0);
        rd_chk(1'b0, A_STATUS, 32'h0000_0000, 1'b0);
        wr_chk(1'b0, A_RISE, 32'h0000_0000, 4'hF, 1'b0);

        // Phase 12: N = 32 detection in the upper lanes.
        phase = 12;
        wr_chk(1'b1, A_RISE, 32'h8000_0000, 4'hF, 1'b0);
        wr_chk(1'b1, A_ENABLE, 32'h8000_0000, 4'hF, 1'b0);
        wr_chk(1'b1, A_HIGH, 32'h0001_0000, 4'hF, 1'b0);
        gpio_in32 = 32'h8001_0000;
        idle(2);
        rd_chk(1'b1, A_STATUS, 32'h8001_0000, 1'b0);
        check32({31'h0, irq32}, 32'h0000_0001);
        wr_chk(1'b1, A_STATUS, 32'h8001_0000, 4'hF, 1'b0);
        rd_chk(1'b1, A_STATUS, 32'h0001_0000, 1'b0);
        check32({31'h0, irq32}, 32'h0000_0000);
        wr_chk(1'b1, A_HIGH, 32'h0000_0000, 4'hF, 1'b0);
        wr_chk(1'b1, A_STATUS, 32'hFFFF_FFFF, 4'hF, 1'b0);
        rd_chk(1'b1, A_STATUS, 32'h0000_0000, 1'b0);
        wr_chk(1'b1, A_RISE, 32'h0000_0000, 4'hF, 1'b0);
        wr_chk(1'b1, A_ENABLE, 32'h0000_0000, 4'hF, 1'b0);

        // Phase 13: reset again with state pending.
        phase = 13;
        wr_chk(1'b0, A_DATA_OUT, 32'h0000_005A, 4'hF, 1'b0);
        wr_chk(1'b0, A_DIR, 32'h0000_003C, 4'hF, 1'b0);
        wr_chk(1'b0, A_HIGH, 32'h0000_0001, 4'hF, 1'b0);
        wr_chk(1'b0, A_ENABLE, 32'h0000_0001, 4'hF, 1'b0);
        wr_chk(1'b1, A_DATA_OUT, 32'hCAFE_0001, 4'hF, 1'b0);
        idle(2);
        check32({31'h0, irq8}, 32'h0000_0001);
        check32({24'h0, gpio_out8}, 32'h0000_005A);
        check32({24'h0, gpio_oe8}, 32'h0000_003C);
        check32(gpio_out32, 32'hCAFE_0001);
        presetn = 1'b0;
        idle(2);
        check32({24'h0, gpio_out8}, 32'h0000_0000);
        check32({24'h0, gpio_oe8}, 32'h0000_0000);
        check32({31'h0, irq8}, 32'h0000_0000);
        check32(gpio_out32, 32'h0000_0000);
        check32({31'h0, irq32}, 32'h0000_0000);
        check32(dut8.in_q, 32'h0000_0000);
        check32(dut8.in_prev, 32'h0000_0000);
        check32(dut8.status, 32'h0000_0000);
        presetn = 1'b1;
        check32(dut8.in_q, 32'h0000_0000);
        check32(dut8.in_prev, 32'h0000_0000);
        gpio_in8  = 8'h00;
        gpio_in32 = 32'h0000_0000;
        for (a = 8'h00; a <= 8'h20; a = a + 8'h04) begin
            rd_chk(1'b0, a, 32'h0000_0000, 1'b0);
            rd_chk(1'b1, a, 32'h0000_0000, 1'b0);
        end
        check32({31'h0, irq8}, 32'h0000_0000);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
